document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("route-map");if(!e)return;const n=e.dataset.gpx;if(!n)return;const t=L.map(e);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"&copy; OpenStreetMap contributors",maxZoom:19}).addTo(t),fetch(n).then(e=>{if(!e.ok)throw new Error(`Could not load GPX: ${e.status}`);return e.text()}).then(e=>{const s=new DOMParser,o=s.parseFromString(e,"application/xml"),n=[],i=o.querySelectorAll("trkpt");if(i.forEach(e=>{const t=parseFloat(e.getAttribute("lat")),s=parseFloat(e.getAttribute("lon"));!Number.isNaN(t)&&!Number.isNaN(s)&&n.push([t,s])}),!n.length)throw new Error("No track points found in GPX");const a=L.polyline(n,{color:"#111",weight:4,opacity:.9,lineJoin:"round",lineCap:"round"}).addTo(t);t.fitBounds(a.getBounds(),{padding:[30,30]})}).catch(t=>{console.error("Pyrimoto GPX:",t),e.innerHTML="";const n=document.createElement("p");n.textContent="No s'ha pogut carregar la ruta.",e.appendChild(n)})})